package com.nthexperience.desktop;

import android.content.Context;
import android.os.*;
import android.text.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;

/** Native working tools behind the compact gadget faces. */
final class GadgetPanel extends VistaShell {
    interface Host extends Actions {void changed();void feed(String url);void refreshFeed();void article(String url);}
    private final String kind;private final Host host;private final FeedClient feeds;private final GadgetHardware hardware;private GadgetView preview;private GridLayout puzzleGrid;
    private final Handler main=new Handler(Looper.getMainLooper());private boolean closed,active=true;
    private TextView reading,startButton,pauseButton,feedStatus;private LinearLayout tasksList,lapsList,feedList;private EditText minutes;private String lastLaps="";
    private final Runnable tick=new Runnable(){public void run(){if(closed||!active||!isShown())return;readings();main.postDelayed(this,kind.equals("stopwatch")?100:1000);}};
    GadgetPanel(Context c,DesktopStore store,String kind,FeedClient feeds,GadgetHardware hardware,Host host){super(c,store,host,"Search gadgets");this.kind=kind;this.feeds=feeds;this.hardware=hardware;this.host=host;search.setVisibility(GONE);start("home");}
    @Override void render(){
        side.removeAllViews();sideLink("Gadget Gallery",()->host.open("@gadgets"));sideLink("Personalization",()->host.open("@appearance"));address.setText("Gadgets  ›  "+GadgetCatalog.title(kind));status.setText("Nth Desktop  •  "+GadgetCatalog.title(kind));LinearLayout column=column();heading(column,GadgetCatalog.title(kind),GadgetCatalog.description(kind));reading=null;tasksList=null;lapsList=null;feedList=null;
        switch(kind){case "worldclock":world(column);break;case "checklist":checklist(column);break;case "timer":case "stopwatch":timeTool(column);break;case "calculator":calculator(column);break;case "converter":converter(column);break;case "storage":storage(column);break;case "feeds":feed(column);break;case "network":case "compass":hardware(column);break;case "puzzle":puzzle(column);break;}
        if(GadgetExtras.supports(kind))GadgetExtras.build(getContext(),store,kind,column,this::changed);
        body(scrolling(column));readings();active(true);
    }
    private TextView button(LinearLayout column,String title,Runnable action){TextView button=Aero.button(getContext(),title,action);button.setContentDescription(title);LayoutParams p=new LayoutParams(-1,dp(43));p.topMargin=dp(6);column.addView(button,p);return button;}
    private EditText input(LinearLayout column,String description,String value){EditText input=new EditText(getContext());input.setTypeface(Aero.face(getContext()));input.setTextSize(15);input.setSingleLine(true);input.setText(value);input.setContentDescription(description);column.addView(input,new LayoutParams(-1,dp(46)));return input;}
    private void changed(){host.changed();readings();}
    private void world(LinearLayout column){JSONObject data=GadgetData.get(store,kind);String[] zones=TimeZone.getAvailableIDs();Arrays.sort(zones);for(int i=1;i<=2;i++){String key="zone"+i;String current=data.optString(key,i==1?"Europe/London":"Asia/Tokyo");Spinner spinner=spinner(column,"World clock zone "+i,zones,Math.max(0,Arrays.asList(zones).indexOf(current)));spinner.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int position,long id){JSONObject value=GadgetData.get(store,kind);GadgetLayout.put(value,key,zones[position]);GadgetData.save(store,kind,value);changed();}});}reading=Aero.text(getContext(),"",18,Aero.INK);reading.setPadding(0,dp(15),0,dp(10));reading.setContentDescription("World clock times");column.addView(reading);}
    private Spinner spinner(LinearLayout column,String title,String[] values,int selected){TextView label=Aero.text(getContext(),title,12,0xff586976);column.addView(label);Spinner spinner=new Spinner(getContext());spinner.setContentDescription(title);ArrayAdapter<String> adapter=new ArrayAdapter<String>(getContext(),android.R.layout.simple_spinner_item,values){@Override public View getView(int position,View recycled,ViewGroup parent){TextView text=Aero.text(getContext(),getItem(position),13,Aero.INK);text.setPadding(dp(8),dp(7),dp(4),dp(7));return text;}@Override public View getDropDownView(int position,View recycled,ViewGroup parent){TextView text=(TextView)super.getDropDownView(position,recycled,parent);text.setTypeface(Aero.face(getContext()));text.setTextSize(14);text.setTextColor(Aero.INK);text.setPadding(dp(12),dp(10),dp(12),dp(10));text.setMinHeight(dp(44));text.setBackground(Aero.selection(getContext()));return text;}};spinner.setPopupBackgroundDrawable(Aero.panel(getContext(),0xfffafcfd,0xffeef3f7,2,0xff7e9aac));adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);spinner.setAdapter(adapter);spinner.setSelection(Math.max(0,Math.min(values.length-1,selected)));column.addView(spinner,new LayoutParams(-1,dp(44)));return spinner;}
    private void checklist(LinearLayout column){EditText input=input(column,"New checklist item","");input.setHint("Add a task…");input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(180)});button(column,"Add checklist item",()->{String text=input.getText().toString().trim();if(text.isEmpty()){input.setError("Enter a task");return;}JSONObject data=GadgetData.get(store,kind);JSONArray tasks=data.optJSONArray("tasks");if(tasks==null)tasks=new JSONArray();if(tasks.length()>=50){input.setError("50 tasks are already saved");return;}JSONObject task=new JSONObject();GadgetLayout.put(task,"text",text);GadgetLayout.put(task,"done",false);tasks.put(task);GadgetLayout.put(data,"tasks",tasks);GadgetData.save(store,kind,data);input.setText("");tasks();changed();});tasksList=Aero.column(getContext());column.addView(tasksList);button(column,"Clear completed tasks",()->{JSONObject data=GadgetData.get(store,kind);JSONArray old=data.optJSONArray("tasks"),keep=new JSONArray();if(old!=null)for(int i=0;i<old.length();i++)if(old.optJSONObject(i)!=null&&!old.optJSONObject(i).optBoolean("done"))keep.put(old.optJSONObject(i));GadgetLayout.put(data,"tasks",keep);GadgetData.save(store,kind,data);tasks();changed();});tasks();}
    private void tasks(){if(tasksList==null)return;tasksList.removeAllViews();JSONArray tasks=GadgetData.get(store,kind).optJSONArray("tasks");if(tasks==null)return;for(int i=0;i<tasks.length();i++){JSONObject item=tasks.optJSONObject(i);if(item==null)continue;int index=i;LinearLayout row=new LinearLayout(getContext());CheckBox check=Aero.check(getContext(),item.optString("text"),item.optBoolean("done"));check.setContentDescription("Checklist task: "+item.optString("text"));row.addView(check,new LayoutParams(0,-2,1));check.setOnCheckedChangeListener((v,value)->{JSONObject data=GadgetData.get(store,kind);JSONArray entries=data.optJSONArray("tasks");if(entries!=null&&entries.optJSONObject(index)!=null){GadgetLayout.put(entries.optJSONObject(index),"done",value);GadgetData.save(store,kind,data);changed();}});TextView remove=Aero.button(getContext(),"×",()->{JSONObject data=GadgetData.get(store,kind);JSONArray entries=data.optJSONArray("tasks");if(entries!=null){entries.remove(index);GadgetData.save(store,kind,data);tasks();changed();}});remove.setContentDescription("Delete checklist task: "+item.optString("text"));row.addView(remove,new LayoutParams(dp(40),dp(43)));tasksList.addView(row);}}
    private void timeTool(LinearLayout column){JSONObject data=GadgetData.get(store,kind);reading=Aero.text(getContext(),"",30,0xff234f75);reading.setGravity(Gravity.CENTER);reading.setContentDescription(kind.equals("timer")?"Countdown remaining":"Stopwatch elapsed");column.addView(reading,new LayoutParams(-1,dp(65)));
        if(kind.equals("timer")){minutes=input(column,"Countdown minutes",Long.toString(Math.max(1,data.optLong("duration",300000)/60000)));minutes.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);}
        startButton=button(column,kind.equals("timer")?"Start or resume countdown":"Start stopwatch",()->{JSONObject state=GadgetData.get(store,kind);if(kind.equals("timer")){int duration;try{duration=Integer.parseInt(minutes.getText().toString());if(duration<1||duration>1440)throw new NumberFormatException();}catch(NumberFormatException ex){minutes.setError("Choose 1 to 1440 minutes");return;}long remaining=GadgetData.value(store,kind);if(remaining==0||state.optLong("duration",300000)!=duration*60000L||!state.optBoolean("started"))remaining=duration*60000L;GadgetLayout.put(state,"duration",duration*60000L);GadgetLayout.put(state,"remaining",remaining);GadgetLayout.put(state,"started",true);}else GadgetLayout.put(state,"elapsed",GadgetData.value(store,kind));GadgetData.start(state,StartupExperience.boot(getContext()));GadgetData.save(store,kind,state);changed();});
        pauseButton=button(column,kind.equals("timer")?"Pause countdown":"Pause stopwatch",()->{JSONObject state=GadgetData.get(store,kind);GadgetLayout.put(state,kind.equals("timer")?"remaining":"elapsed",GadgetData.value(store,kind));GadgetLayout.put(state,"running",false);GadgetData.save(store,kind,state);changed();});
        button(column,kind.equals("timer")?"Reset countdown":"Reset stopwatch",()->{JSONObject state=GadgetData.get(store,kind);GadgetLayout.put(state,"running",false);GadgetLayout.put(state,"started",false);GadgetLayout.put(state,kind.equals("timer")?"remaining":"elapsed",kind.equals("timer")?state.optLong("duration",300000):0);GadgetLayout.put(state,"laps",new JSONArray());GadgetData.save(store,kind,state);changed();});
        if(kind.equals("stopwatch")){button(column,"Save lap",()->{JSONObject state=GadgetData.get(store,kind);JSONArray laps=state.optJSONArray("laps");if(laps==null)laps=new JSONArray();if(laps.length()>=20)laps.remove(0);laps.put(GadgetData.value(store,kind));GadgetLayout.put(state,"laps",laps);GadgetData.save(store,kind,state);readings();});lapsList=Aero.column(getContext());column.addView(lapsList);}else{TextView hint=Aero.text(getContext(),"Completion appears here when you return. This countdown does not ring an Android alarm.",12,0xff586976);hint.setPadding(0,dp(12),0,0);column.addView(hint);}}
    private void calculator(LinearLayout column){JSONObject data=GadgetData.get(store,kind);EditText expression=input(column,"Calculator expression",data.optString("expression",""));expression.setFilters(new InputFilter[]{new InputFilter.LengthFilter(120)});reading=Aero.text(getContext(),data.optString("result","0"),27,0xff234f75);reading.setContentDescription("Calculator result");column.addView(reading,new LayoutParams(-1,dp(52)));expression.addTextChangedListener(watch(()->{JSONObject state=GadgetData.get(store,kind);GadgetLayout.put(state,"expression",expression.getText().toString());GadgetData.save(store,kind,state);}));GridLayout keys=new GridLayout(getContext());keys.setColumnCount(4);column.addView(keys,new LayoutParams(-1,-2));for(String key:new String[]{"C","⌫","(",")","7","8","9","÷","4","5","6","×","1","2","3","−","0",".","%","+","="}){TextView button=Aero.button(getContext(),key,()->{if(key.equals("C")){expression.setText("");reading.setText("0");JSONObject state=GadgetData.get(store,kind);GadgetLayout.put(state,"result","0");GadgetData.save(store,kind,state);changed();}else if(key.equals("⌫")){String text=expression.getText().toString();if(!text.isEmpty())expression.setText(text.substring(0,text.length()-1));}else if(key.equals("=")){try{String value=GadgetMath.number(GadgetMath.evaluate(expression.getText().toString()));reading.setText(value);JSONObject state=GadgetData.get(store,kind);GadgetLayout.put(state,"result",value);GadgetData.save(store,kind,state);changed();}catch(IllegalArgumentException ex){reading.setText(ex.getMessage());}}else expression.append(key.equals("−")?"-":key);expression.setSelection(expression.length());});button.setContentDescription("Calculator "+key);GridLayout.LayoutParams p=new GridLayout.LayoutParams();p.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);p.width=0;p.height=dp(43);p.setMargins(dp(2),dp(2),dp(2),dp(2));keys.addView(button,p);}}
    private void converter(LinearLayout column){JSONObject data=GadgetData.get(store,kind);int initial=Math.max(0,Math.min(GadgetMath.CATEGORIES.length-1,data.optInt("category",0)));Spinner category=spinner(column,"Conversion category",GadgetMath.CATEGORIES,initial);EditText value=input(column,"Value to convert",data.optString("input","1"));value.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL|android.text.InputType.TYPE_NUMBER_FLAG_SIGNED);value.setFilters(new InputFilter[]{new InputFilter.LengthFilter(64)});LinearLayout units=Aero.column(getContext());column.addView(units);Spinner[] from=new Spinner[1],to=new Spinner[1];int[] current={initial};reading=Aero.text(getContext(),"",23,0xff234f75);reading.setContentDescription("Conversion result");column.addView(reading,new LayoutParams(-1,dp(60)));
        Runnable calculate=()->{if(from[0]==null||to[0]==null||from[0].getSelectedItemPosition()<0||to[0].getSelectedItemPosition()<0)return;int a=from[0].getSelectedItemPosition(),b=to[0].getSelectedItemPosition();JSONObject state=new JSONObject();GadgetLayout.put(state,"category",current[0]);GadgetLayout.put(state,"from",a);GadgetLayout.put(state,"to",b);GadgetLayout.put(state,"input",value.getText().toString());GadgetData.save(store,kind,state);try{reading.setText(GadgetMath.number(GadgetMath.convert(Double.parseDouble(value.getText().toString()),current[0],a,b))+" "+GadgetMath.UNITS[current[0]][b]);}catch(RuntimeException ex){reading.setText("Enter a valid number");}host.changed();};
        Runnable rebuild=()->{JSONObject saved=GadgetData.get(store,kind);boolean same=saved.optInt("category",initial)==current[0];units.removeAllViews();from[0]=null;to[0]=null;from[0]=spinner(units,"From unit",GadgetMath.UNITS[current[0]],same?saved.optInt("from",0):0);to[0]=spinner(units,"To unit",GadgetMath.UNITS[current[0]],same?saved.optInt("to",1):1);AdapterView.OnItemSelectedListener listener=new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int position,long id){calculate.run();}};from[0].setOnItemSelectedListener(listener);to[0].setOnItemSelectedListener(listener);calculate.run();};rebuild.run();category.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int position,long id){if(current[0]!=position){current[0]=position;rebuild.run();}}});value.addTextChangedListener(watch(calculate));}
    private void hardware(LinearLayout column){
        preview=new GadgetView(getContext(),kind,store,null);preview.hardware=hardware;LayoutParams face=new LayoutParams(dp(180),dp(GadgetView.height(kind)*180f/132));face.gravity=Gravity.CENTER_HORIZONTAL;column.addView(preview,face);
        reading=Aero.text(getContext(),"",15,Aero.INK);reading.setContentDescription(kind.equals("network")?"Live network readings":"Compass reading");reading.setPadding(0,dp(12),0,dp(12));column.addView(reading);
        TextView hint=Aero.text(getContext(),kind.equals("network")?"Rates are measured across device network interfaces while Nth Desktop is visible. Totals reset at device reboot; these are not carrier billing totals.":"The top edge of your screen points at this magnetic bearing. Hold the phone flat and keep it away from magnets. If accuracy is low, move it in a figure eight.",12,0xff586976);hint.setTypeface(android.graphics.Typeface.create(Aero.face(getContext()),android.graphics.Typeface.ITALIC));column.addView(hint);
    }
    private void puzzle(LinearLayout column){
        if(!GadgetData.get(store,kind).has("board"))TilePuzzle.save(store,TilePuzzle.shuffle(new Random()),0);
        reading=Aero.text(getContext(),"",15,Aero.INK);reading.setContentDescription("Puzzle progress");column.addView(reading);puzzleGrid=new GridLayout(getContext());puzzleGrid.setColumnCount(4);column.addView(puzzleGrid,new LayoutParams(-1,-2));
        button(column,"New puzzle",()->{TilePuzzle.save(store,TilePuzzle.shuffle(new Random()),0);puzzleBoard();changed();});puzzleBoard();
    }
    private void puzzleBoard(){
        if(puzzleGrid==null)return;puzzleGrid.removeAllViews();JSONObject data=GadgetData.get(store,kind);int[] board=TilePuzzle.board(data);reading.setText((TilePuzzle.solved(board)?"Solved!  •  ":"")+data.optInt("moves",0)+" moves");
        for(int i=0;i<16;i++){int position=i,tile=board[i];TextView key=Aero.button(getContext(),tile==0?"":Integer.toString(tile),()->{int[] current=TilePuzzle.board(GadgetData.get(store,kind));if(TilePuzzle.move(current,position)){TilePuzzle.save(store,current,GadgetData.get(store,kind).optInt("moves",0)+1);puzzleBoard();changed();}});key.setTextSize(24);key.setContentDescription(tile==0?"Puzzle empty cell":"Move puzzle tile "+tile);key.setEnabled(tile!=0);int color=(Math.max(1,tile)-1)/4;int[] tops={0xffe9c37d,0xffb6d4ad,0xffadcfe2,0xffd0bfe0},bottoms={0xffbd8a4c,0xff729b70,0xff6e9fb9,0xff9b83b2};key.setBackground(Aero.gloss(getContext(),new int[]{tops[color],bottoms[color]},4,0xff806a4b));GridLayout.LayoutParams p=new GridLayout.LayoutParams(GridLayout.spec(i/4),GridLayout.spec(i%4,1f));p.width=0;p.height=dp(62);p.setMargins(dp(2),dp(2),dp(2),dp(2));puzzleGrid.addView(key,p);}
    }
    private void storage(LinearLayout column){reading=Aero.text(getContext(),"",17,Aero.INK);reading.setContentDescription("Internal storage readings");column.addView(reading);button(column,"Refresh storage readings",this::readings);button(column,"Android storage settings",()->host.action("android:storage"));}
    private void feed(LinearLayout column){EditText address=input(column,"Feed address",feeds.url());address.setHint("https://www.nasa.gov/feed/");address.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);address.setFilters(new InputFilter[]{new InputFilter.LengthFilter(2048)});button(column,"Use NASA headlines",()->address.setText("https://www.nasa.gov/feed/"));button(column,"Save feed and add gadget",()->{String value=address.getText().toString().trim();if(!FeedClient.validUrl(value)){address.setError("Enter an HTTPS RSS or Atom address");return;}host.feed(value);});button(column,"Refresh headlines",host::refreshFeed);feedStatus=Aero.text(getContext(),"",12,0xff586976);feedStatus.setContentDescription("Feed status");column.addView(feedStatus);feedList=Aero.column(getContext());column.addView(feedList);}
    void readings(){if(closed)return;if(preview!=null)preview.invalidate();if(kind.equals("network")&&reading!=null)reading.setText("Receive: "+GadgetHardware.speed(hardware.down)+"\nSend: "+GadgetHardware.speed(hardware.up)+"\n\nSince device boot\nReceived: "+(hardware.received<0?"Unavailable":android.text.format.Formatter.formatFileSize(getContext(),hardware.received))+"\nSent: "+(hardware.sent<0?"Unavailable":android.text.format.Formatter.formatFileSize(getContext(),hardware.sent)));if(kind.equals("compass")&&reading!=null)reading.setText((Float.isFinite(hardware.heading)?Math.round(hardware.heading)+"° magnetic\n":"")+hardware.compassStatus);JSONObject data=GadgetData.get(store,kind);if(reading!=null){if(kind.equals("worldclock")){StringBuilder value=new StringBuilder();for(int i=1;i<=2;i++){String zone=data.optString("zone"+i,i==1?"Europe/London":"Asia/Tokyo");java.text.SimpleDateFormat format=new java.text.SimpleDateFormat("EEE, MMM d  •  HH:mm:ss z",Locale.getDefault());format.setTimeZone(TimeZone.getTimeZone(zone));if(i>1)value.append("\n\n");value.append(zone.replace('_',' ')).append("\n").append(format.format(new Date()));}reading.setText(value);}else if(kind.equals("timer")||kind.equals("stopwatch")){long value=GadgetData.value(store,kind);reading.setText(kind.equals("timer")&&data.optBoolean("started")&&value==0?"Time’s up":GadgetData.duration(value,kind.equals("stopwatch")));boolean running=data.optBoolean("running")&&(!kind.equals("timer")||value>0);if(startButton!=null)startButton.setEnabled(!running);if(pauseButton!=null)pauseButton.setEnabled(running);if(lapsList!=null&&!lastLaps.equals(data.optString("laps","[]"))){lastLaps=data.optString("laps","[]");lapsList.removeAllViews();JSONArray laps=data.optJSONArray("laps");if(laps!=null)for(int i=0;i<laps.length();i++)lapsList.addView(Aero.text(getContext(),"Lap "+(i+1)+"   "+GadgetData.duration(laps.optLong(i),true),13,Aero.INK));}}else if(kind.equals("storage"))try{StatFs disk=new StatFs(Environment.getDataDirectory().getPath());long total=disk.getTotalBytes(),free=disk.getAvailableBytes();reading.setText("Internal storage\n\n"+android.text.format.Formatter.formatFileSize(getContext(),free)+" available\n"+android.text.format.Formatter.formatFileSize(getContext(),total-free)+" used\n"+android.text.format.Formatter.formatFileSize(getContext(),total)+" total");}catch(RuntimeException ex){reading.setText("Storage information unavailable");}}
        if(feedList!=null){feedStatus.setText(feeds.status());feedList.removeAllViews();JSONArray items=FeedClient.items(store);for(int i=0;i<items.length();i++){JSONObject item=items.optJSONObject(i);if(item!=null)button(feedList,item.optString("title"),()->host.article(item.optString("url")));}}
    }
    private TextWatcher watch(Runnable changed){return new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){changed.run();}public void afterTextChanged(Editable e){}};}
    void active(boolean value){active=value;main.removeCallbacks(tick);if(value&&!closed&&(kind.equals("timer")||kind.equals("stopwatch")||kind.equals("worldclock")))main.postDelayed(tick,100);}
    @Override protected void onVisibilityChanged(View changed,int visibility){super.onVisibilityChanged(changed,visibility);if(main!=null)active(visibility==VISIBLE&&getWindowVisibility()==VISIBLE);}
    @Override void showFolders(){host.open("@gadgets");}
    @Override void goUp(){host.open("@gadgets");}
    @Override void close(){closed=true;main.removeCallbacksAndMessages(null);}
}
